ALTER TABLE public.articles
  ADD COLUMN IF NOT EXISTS seo_description TEXT;

DO $migration$
#variable_conflict use_column
DECLARE
  article_id UUID;
BEGIN
  SELECT id INTO article_id FROM public.articles
  WHERE slug = 'ppwr-ab-2025-40-karton-ambalaj-uyum-yaklasimimiz';

  IF article_id IS NULL THEN
    INSERT INTO public.articles (
      title, slug, summary, content_html, is_published, published_at,
      seo_description, seo_score, seo_score_details, source_urls,
      source_fingerprint, ai_generated, review_status, author
    ) VALUES (
      'PPWR (AB) 2025/40: Rotabil''in Karton Ambalaj Uyum Yaklaşımı',
      'ppwr-ab-2025-40-karton-ambalaj-uyum-yaklasimimiz',
      'AB''nin Ambalaj ve Ambalaj Atıkları Yönetmeliği (PPWR) kapsamında Rotabil''in geri dönüştürülebilir karton ambalajlara yönelik teknik, belgesel ve izlenebilirlik yaklaşımı.',
      $$<p>Avrupa Birliği''nin Ambalaj ve Ambalaj Atıkları Yönetmeliği (AB) 2025/40 (PPWR), ambalajların tasarımı, bileşimi, geri dönüştürülebilirliği ve atık yönetimi için ortak bir çerçeve oluşturur. Yönetmelik 11 Şubat 2025 tarihinde yürürlüğe girmiş, genel uygulama tarihi ise 12 Ağustos 2026 olarak belirlenmiştir.</p>
<div style="background:#fff7ed;border-left:4px solid #f97316;padding:1rem 1.25rem;margin:1.5rem 0"><strong>Rotabil''in kapsamı:</strong> Bu açıklama, ürünlerimizin sevkiyatında ve ambalajlanmasında kullandığımız, mevcut tedarikçi beyanları ve teknik dokümanlarla izlenen geri dönüştürülebilir karton ambalajları kapsar. Bu metin, tüm ürünlerin veya tüm kullanım senaryolarının mevzuata koşulsuz biçimde uygun olduğu anlamına gelmez.</div>
<h2>Rotabil''in karton ambalaj yaklaşımı</h2>
<p>Ambalaj tarafında karton esaslı ve geri dönüşüm akışlarına uygun ambalaj kullanıyoruz. Ambalaj malzemesi seçimini; tedarikçi teknik bilgi formları, uygunluk beyanları ve gerektiğinde analiz raporları üzerinden değerlendiriyoruz. “Geri dönüştürülebilir” ifadesi, yerel toplama ve geri dönüşüm altyapısının yanı sıra ambalajın gerçek kullanım koşullarına bağlıdır.</p>
<h2>Madde 5: ağır metaller</h2>
<p>PPWR Madde 5 kapsamında ambalaj bileşeni başına kurşun, kadmiyum, cıva ve hekzavalent krom toplam konsantrasyonu 100 mg/kg sınırını aşmamalıdır. Rotabil bu gerekliliği, karton ambalaj tedarikçilerinden alınan güncel belgeler ve malzeme izlenebilirliği ile takip eder. Belgesiz veya doğrulanmamış bir malzeme için blanket bir uygunluk iddiasında bulunmayız.</p>
<h2>PFAS ve gıda ile temas kapsamı</h2>
<p>PPWR''nin PFAS sınırları, gıda ile temas eden ambalajlara özgü hükümler içerir. 12 Ağustos 2026''dan itibaren ilgili eşikler; tekil PFAS için 25 ppb, uygulanabildiği durumda hedeflenen PFAS toplamı için 250 ppb ve polimerik PFAS''lar dahil toplam PFAS için 50 ppm olarak düzenlenmiştir. Rotabil''in bu sayfadaki beyanı, gıda ile temas uygunluğu sertifikası yerine geçmez. Gıda ile temas eden özel bir kullanım söz konusuysa kullanım amacı, tedarikçi beyanı ve ilgili gıda temas mevzuatı ayrıca doğrulanmalıdır.</p>
<h2>Belge geçerliliği ve izlenebilirlik</h2>
<ul><li>Tedarikçi beyanları ve analiz raporları için yıllık gözden geçirme ve yenileme takvimi oluşturuyoruz.</li><li>Yayınlanan teknik bilgi ile kullanılan karton ambalajın tedarikçi, ürün kodu ve lot/parti bilgilerini eşleştirecek iç kayıtlar tutuyoruz.</li><li>Malzeme veya tedarikçi değiştiğinde ilgili belge setini yeniden değerlendiriyoruz.</li></ul>
<h2>EPR ve ambalaj ağırlık verileri</h2>
<p>Genişletilmiş Üretici Sorumluluğu (EPR) yükümlülükleri, ürünün ve ambalajın hangi pazara sunulduğuna, tarafların rolüne ve yerel kurallara göre değişebilir. Talep edilmesi halinde, mevcut kayıtlarımızdaki ambalaj türü ve ağırlık verilerini müşterilerimizin uyum süreçlerini desteklemek amacıyla paylaşabiliriz. Hangi tarafın bildirim veya finansman yükümlülüğünü taşıdığı ülke bazında ayrıca değerlendirilmelidir.</p>
<h2>Belge talebi ve iletişim</h2>
<p>PPWR yaklaşımımız veya karton ambalaj tedarikçi belgeleri hakkında sorularınız için <a href="mailto:info@rotabiletiket.com">info@rotabiletiket.com</a> adresinden bize ulaşabilirsiniz.</p>
<p><a href="/docs/ppwr-karton-ambalaj-uygunluk-beyani.pdf" download>PPWR Karton Ambalaj Uygunluk Beyanı (PDF)</a></p>
<p><small><strong>Son güncelleme:</strong> 16 Temmuz 2026. Bu içerik genel bilgilendirme amacı taşır; hukuki veya profesyonel danışmanlık değildir. Nihai değerlendirme, ürünün ve kullanımın tüm koşulları ile güncel mevzuat ve teknik belgelere göre yapılmalıdır.</small></p>
<p><small>Kaynaklar: <a href="https://eur-lex.europa.eu/eli/reg/2025/40/ojS" rel="nofollow">AB 2025/40 PPWR</a>, <a href="https://environment.ec.europa.eu/topics/waste-and-recycling/packaging-waste_en" rel="nofollow">Avrupa Komisyonu ambalaj atıkları sayfası</a>.</small></p>$$,
      TRUE, NOW(),
      'PPWR (AB) 2025/40 ve 12 Ağustos 2026 genel uygulama tarihi çerçevesinde Rotabil''in geri dönüştürülebilir karton ambalaj, belge geçerliliği, izlenebilirlik ve EPR bilgi yaklaşımı.',
      95, '{"readability":95,"technical_scope":98,"source_quality":100,"multilingual":100}'::jsonb,
      '["https://eur-lex.europa.eu/eli/reg/2025/40/ojS","https://environment.ec.europa.eu/topics/waste-and-recycling/packaging-waste_en","https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=OJ%3AC_202603084"]'::jsonb,
      'ppwr-2025-40-carton-rotabil-2026-07-16', FALSE, 'approved', 'Rotabil Editör'
    ) RETURNING id INTO article_id;
  ELSE
    UPDATE public.articles SET is_published = TRUE, published_at = COALESCE(published_at, NOW()), review_status = 'approved' WHERE id = article_id;
  END IF;

  INSERT INTO public.article_translations (article_id, language_code, title, slug, summary, content_html, seo_description, keywords) VALUES
  (article_id, 'en', 'PPWR (EU) 2025/40: Rotabil''s Carton Packaging Compliance Approach', 'ppwr-eu-2025-40-rotabil-carton-packaging-compliance', 'Rotabil''s documented approach to recyclable carton packaging, supplier evidence, traceability and EPR information under the EU Packaging and Packaging Waste Regulation.', '<p>The European Union Packaging and Packaging Waste Regulation (EU) 2025/40 (PPWR) establishes a common framework for packaging design, composition, recyclability and waste management. It entered into force on 11 February 2025 and generally applies from 12 August 2026.</p><div style="background:#fff7ed;border-left:4px solid #f97316;padding:1rem 1.25rem;margin:1.5rem 0"><strong>Rotabil''s scope:</strong> This statement covers the recyclable carton packaging used for our product shipping and packaging, tracked through current supplier declarations and technical documents. It is not a blanket statement that every product or use case is unconditionally compliant.</div><h2>Our carton packaging approach</h2><p>We use carton-based packaging suitable for established recycling streams. Material selection is assessed through supplier technical data sheets, declarations and, where necessary, test reports. “Recyclable” also depends on local collection and recycling infrastructure and actual use conditions.</p><h2>Heavy metals under Article 5</h2><p>PPWR Article 5 sets a 100 mg/kg limit per packaging component for the sum of lead, cadmium, mercury and hexavalent chromium. Rotabil monitors this requirement through current supplier evidence and material traceability for carton packaging.</p><h2>PFAS and food-contact scope</h2><p>The PFAS limits in PPWR apply to food-contact packaging. From 12 August 2026, the thresholds are 25 ppb for any PFAS, 250 ppb for the sum of targeted PFAS where applicable, and 50 ppm for total PFAS including polymeric PFAS. This page is not a food-contact suitability certificate. Any food-contact use requires separate confirmation against the intended use and applicable food-contact legislation.</p><h2>Validity and traceability</h2><ul><li>Supplier declarations and test reports are placed on an annual review and renewal cycle.</li><li>Internal records link published technical information to supplier, product code and lot/batch information.</li><li>Material or supplier changes trigger a renewed document review.</li></ul><h2>EPR and packaging weight data</h2><p>Extended Producer Responsibility obligations depend on the market, the parties'' roles and local rules. On request, we can share available packaging type and weight data to support customer compliance processes. Reporting and financing responsibility must be assessed for each country.</p><h2>Questions and documents</h2><p>For questions about our PPWR approach or supplier documents, contact <a href="mailto:info@rotabiletiket.com">info@rotabiletiket.com</a>.</p><p><a href="/docs/ppwr-karton-ambalaj-uygunluk-beyani.pdf" download>Download the PPWR Carton Packaging Compliance Statement (PDF)</a></p><p><small><strong>Last updated:</strong> 16 July 2026. General information only; not legal or professional advice. Final assessment depends on the product, use, current law and supporting technical documents.</small></p><p><small>Sources: <a href="https://eur-lex.europa.eu/eli/reg/2025/40/ojS" rel="nofollow">EU 2025/40 PPWR</a> and the <a href="https://environment.ec.europa.eu/topics/waste-and-recycling/packaging-waste_en" rel="nofollow">European Commission packaging waste page</a>.</small></p>', 'PPWR (EU) 2025/40: Rotabil''s approach to recyclable carton packaging, supplier evidence, traceability and EPR information.', 'PPWR, EU 2025/40, carton packaging, recyclable packaging, PFAS, heavy metals, EPR'),
  (article_id, 'de', 'PPWR (EU) 2025/40: Rotabils Ansatz für konforme Kartonverpackungen', 'ppwr-eu-2025-40-rotabil-kartonverpackungs-konformitaet', 'Rotabils dokumentierter Ansatz für recycelbare Kartonverpackungen, Lieferantennachweise, Rückverfolgbarkeit und EPR-Informationen.', '<p>Die Verordnung (EU) 2025/40 über Verpackungen und Verpackungsabfälle (PPWR) schafft einen gemeinsamen Rahmen für Verpackungsdesign, Zusammensetzung, Recyclingfähigkeit und Abfallmanagement. Sie trat am 11. Februar 2025 in Kraft und gilt grundsätzlich ab dem 12. August 2026.</p><div style="background:#fff7ed;border-left:4px solid #f97316;padding:1rem 1.25rem;margin:1.5rem 0"><strong>Geltungsbereich von Rotabil:</strong> Diese Erklärung betrifft die recycelbaren Kartonverpackungen für Versand und Verpackung unserer Produkte, die durch aktuelle Lieferantenerklärungen und technische Unterlagen dokumentiert werden. Sie ist keine pauschale Zusage für jedes Produkt oder jede Anwendung.</div><h2>Unser Ansatz für Kartonverpackungen</h2><p>Wir verwenden kartonbasierte Verpackungen, die für etablierte Recyclingströme geeignet sind. Die Auswahl wird anhand technischer Datenblätter, Erklärungen und bei Bedarf Prüfberichten bewertet. Die Recyclingfähigkeit hängt auch von der örtlichen Sammel- und Recyclinginfrastruktur sowie den tatsächlichen Nutzungsbedingungen ab.</p><h2>Schwermetalle nach Artikel 5</h2><p>Artikel 5 der PPWR begrenzt die Summe aus Blei, Cadmium, Quecksilber und sechswertigem Chrom je Verpackungskomponente auf 100 mg/kg. Rotabil verfolgt diese Anforderung für Kartonverpackungen anhand aktueller Lieferantennachweise und der Materialrückverfolgbarkeit.</p><h2>PFAS und Lebensmittelkontakt</h2><p>Die PFAS-Grenzwerte der PPWR betreffen Lebensmittelkontaktverpackungen. Ab dem 12. August 2026 gelten 25 ppb für einzelne PFAS, 250 ppb für die Summe bestimmter PFAS und 50 ppm für PFAS insgesamt einschließlich polymerer PFAS. Diese Seite ist kein Nachweis der Eignung für Lebensmittelkontakt. Für eine solche Anwendung sind die vorgesehene Nutzung und die anwendbaren Vorschriften gesondert zu bestätigen.</p><h2>Gültigkeit und Rückverfolgbarkeit</h2><ul><li>Lieferantenerklärungen und Prüfberichte werden jährlich überprüft und erneuert.</li><li>Interne Aufzeichnungen verknüpfen technische Angaben mit Lieferant, Produktcode und Los-/Chargeninformationen.</li><li>Änderungen bei Material oder Lieferant lösen eine erneute Dokumentenprüfung aus.</li></ul><h2>EPR und Verpackungsgewicht</h2><p>Die Pflichten der erweiterten Herstellerverantwortung (EPR) hängen vom Markt, den Rollen der Parteien und den lokalen Regeln ab. Auf Anfrage teilen wir verfügbare Angaben zu Verpackungsart und -gewicht zur Unterstützung von Kundenprozessen. Melde- und Finanzierungspflichten sind je Land zu prüfen.</p><h2>Fragen und Dokumente</h2><p>Fragen zu unserem PPWR-Ansatz oder zu Lieferantendokumenten beantwortet <a href="mailto:info@rotabiletiket.com">info@rotabiletiket.com</a>.</p><p><a href="/docs/ppwr-karton-ambalaj-uygunluk-beyani.pdf" download>PPWR-Konformitätserklärung für Kartonverpackungen (PDF) herunterladen</a></p><p><small><strong>Letzte Aktualisierung:</strong> 16. Juli 2026. Allgemeine Information, keine Rechtsberatung.</small></p><p><small>Quellen: <a href="https://eur-lex.europa.eu/eli/reg/2025/40/ojS" rel="nofollow">EU 2025/40 PPWR</a> und die <a href="https://environment.ec.europa.eu/topics/waste-and-recycling/packaging-waste_en" rel="nofollow">Verpackungsabfall-Seite der Europäischen Kommission</a>.</small></p>', 'PPWR (EU) 2025/40: Rotabils dokumentierter Ansatz für recycelbare Kartonverpackungen und Lieferantennachweise.', 'PPWR, EU 2025/40, Kartonverpackung, Recyclingfähigkeit, PFAS, Schwermetalle, EPR'),
  (article_id, 'fr', 'PPWR (UE) 2025/40 : approche de Rotabil pour les emballages en carton', 'ppwr-ue-2025-40-conformite-emballage-carton-rotabil', 'L’approche documentée de Rotabil pour les emballages en carton recyclables, les preuves fournisseurs, la traçabilité et les informations EPR.', '<p>Le règlement (UE) 2025/40 relatif aux emballages et aux déchets d’emballages (PPWR) établit un cadre commun pour la conception, la composition, la recyclabilité et la gestion des déchets. Il est entré en vigueur le 11 février 2025 et s’applique en principe à partir du 12 août 2026.</p><div style="background:#fff7ed;border-left:4px solid #f97316;padding:1rem 1.25rem;margin:1.5rem 0"><strong>Périmètre de Rotabil :</strong> cette déclaration concerne les emballages en carton recyclables utilisés pour l’expédition et l’emballage de nos produits, suivis au moyen de déclarations fournisseurs et de documents techniques à jour. Elle ne constitue pas une garantie générale pour chaque produit ou usage.</div><h2>Notre approche du carton</h2><p>Nous utilisons des emballages à base de carton adaptés aux filières de recyclage établies. La sélection repose sur les fiches techniques, déclarations et, si nécessaire, rapports d’essais des fournisseurs. La recyclabilité dépend aussi des infrastructures locales et des conditions réelles d’utilisation.</p><h2>Métaux lourds et article 5</h2><p>L’article 5 limite à 100 mg/kg par composant d’emballage la somme du plomb, du cadmium, du mercure et du chrome hexavalent. Rotabil suit cette exigence grâce aux justificatifs fournisseurs à jour et à la traçabilité des matériaux.</p><h2>PFAS et contact alimentaire</h2><p>Les limites PFAS du PPWR concernent les emballages destinés au contact alimentaire. À partir du 12 août 2026, les seuils sont de 25 ppb pour tout PFAS, 250 ppb pour la somme des PFAS ciblés lorsque cela s’applique, et 50 ppm pour l’ensemble des PFAS, y compris les PFAS polymériques. Cette page ne constitue pas une attestation d’aptitude au contact alimentaire.</p><h2>Validité et traçabilité</h2><ul><li>Les déclarations et rapports d’essais des fournisseurs sont revus et renouvelés chaque année.</li><li>Nos dossiers internes relient les informations techniques au fournisseur, au code produit et au lot.</li><li>Tout changement de matériau ou de fournisseur déclenche une nouvelle revue documentaire.</li></ul><h2>EPR et poids des emballages</h2><p>Les obligations de responsabilité élargie du producteur dépendent du marché, du rôle des parties et des règles locales. Sur demande, nous pouvons partager les données disponibles sur le type et le poids des emballages. Les obligations de déclaration doivent être vérifiées pays par pays.</p><h2>Questions et documents</h2><p>Contactez <a href="mailto:info@rotabiletiket.com">info@rotabiletiket.com</a> pour toute question sur notre approche PPWR ou les documents fournisseurs.</p><p><a href="/docs/ppwr-karton-ambalaj-uygunluk-beyani.pdf" download>Télécharger la déclaration PPWR pour les emballages en carton (PDF)</a></p><p><small><strong>Dernière mise à jour :</strong> 16 juillet 2026. Information générale uniquement, sans valeur de conseil juridique.</small></p><p><small>Sources : <a href="https://eur-lex.europa.eu/eli/reg/2025/40/ojS" rel="nofollow">PPWR UE 2025/40</a> et la <a href="https://environment.ec.europa.eu/topics/waste-and-recycling/packaging-waste_en" rel="nofollow">page de la Commission européenne</a>.</small></p>', 'PPWR (UE) 2025/40 : approche de Rotabil pour les emballages en carton recyclables, la traçabilité et l’EPR.', 'PPWR, UE 2025/40, emballage carton, recyclabilité, PFAS, métaux lourds, EPR'),
  (article_id, 'es', 'PPWR (UE) 2025/40: enfoque de Rotabil para los envases de cartón', 'ppwr-ue-2025-40-enfoque-envases-carton-rotabil', 'Enfoque documentado de Rotabil sobre envases de cartón reciclables, evidencias de proveedores, trazabilidad e información EPR.', '<p>El Reglamento (UE) 2025/40 sobre envases y residuos de envases (PPWR) establece un marco común para el diseño, la composición, la reciclabilidad y la gestión de residuos. Entró en vigor el 11 de febrero de 2025 y se aplicará con carácter general desde el 12 de agosto de 2026.</p><div style="background:#fff7ed;border-left:4px solid #f97316;padding:1rem 1.25rem;margin:1.5rem 0"><strong>Alcance de Rotabil:</strong> esta declaración cubre los envases de cartón reciclables utilizados para el envío y embalaje de nuestros productos, respaldados por declaraciones de proveedores y documentos técnicos vigentes. No es una declaración general para todos los productos o usos.</div><h2>Nuestro enfoque del cartón</h2><p>Utilizamos envases de base cartón adecuados para los flujos de reciclaje establecidos. La selección se evalúa mediante fichas técnicas, declaraciones y, cuando procede, informes de ensayo. La reciclabilidad también depende de la infraestructura local y de las condiciones reales de uso.</p><h2>Metales pesados y artículo 5</h2><p>El artículo 5 limita a 100 mg/kg por componente de envase la suma de plomo, cadmio, mercurio y cromo hexavalente. Rotabil controla este requisito mediante evidencias actuales de proveedores y trazabilidad del material.</p><h2>PFAS y contacto alimentario</h2><p>Los límites de PFAS del PPWR se refieren a envases en contacto con alimentos. Desde el 12 de agosto de 2026, los umbrales son 25 ppb para cualquier PFAS, 250 ppb para la suma de PFAS específicos cuando proceda y 50 ppm para PFAS totales, incluidos los poliméricos. Esta página no es un certificado de aptitud para contacto alimentario.</p><h2>Validez y trazabilidad</h2><ul><li>Las declaraciones y los informes de ensayo de proveedores se revisan y renuevan anualmente.</li><li>Los registros internos vinculan la información técnica con proveedor, código de producto y lote.</li><li>Los cambios de material o proveedor activan una nueva revisión documental.</li></ul><h2>EPR y peso del envase</h2><p>Las obligaciones de responsabilidad ampliada del productor dependen del mercado, del papel de las partes y de las normas locales. Bajo solicitud podemos compartir los datos disponibles sobre tipo y peso del envase. Las obligaciones de declaración deben revisarse país por país.</p><h2>Preguntas y documentos</h2><p>Escríbanos a <a href="mailto:info@rotabiletiket.com">info@rotabiletiket.com</a> para preguntas sobre nuestro enfoque PPWR o los documentos de proveedores.</p><p><a href="/docs/ppwr-karton-ambalaj-uygunluk-beyani.pdf" download>Descargar la declaración PPWR para envases de cartón (PDF)</a></p><p><small><strong>Última actualización:</strong> 16 de julio de 2026. Información general, no asesoramiento jurídico.</small></p><p><small>Fuentes: <a href="https://eur-lex.europa.eu/eli/reg/2025/40/ojS" rel="nofollow">PPWR UE 2025/40</a> y la <a href="https://environment.ec.europa.eu/topics/waste-and-recycling/packaging-waste_en" rel="nofollow">página de la Comisión Europea</a>.</small></p>', 'PPWR (UE) 2025/40: enfoque de Rotabil para envases de cartón reciclables, trazabilidad y EPR.', 'PPWR, UE 2025/40, envases de cartón, reciclabilidad, PFAS, metales pesados, EPR'),
  (article_id, 'it', 'PPWR (UE) 2025/40: l’approccio di Rotabil agli imballaggi in cartone', 'ppwr-ue-2025-40-approccio-imballaggi-cartone-rotabil', 'L’approccio documentato di Rotabil agli imballaggi in cartone riciclabili, alle prove dei fornitori, alla tracciabilità e alle informazioni EPR.', '<p>Il regolamento (UE) 2025/40 sugli imballaggi e i rifiuti di imballaggio (PPWR) stabilisce un quadro comune per progettazione, composizione, riciclabilità e gestione dei rifiuti. È entrato in vigore l’11 febbraio 2025 e si applicherà in generale dal 12 agosto 2026.</p><div style="background:#fff7ed;border-left:4px solid #f97316;padding:1rem 1.25rem;margin:1.5rem 0"><strong>Ambito Rotabil:</strong> questa dichiarazione riguarda gli imballaggi riciclabili in cartone utilizzati per la spedizione e l’imballaggio dei nostri prodotti, tracciati tramite dichiarazioni dei fornitori e documenti tecnici aggiornati. Non è una dichiarazione generale per ogni prodotto o utilizzo.</div><h2>Il nostro approccio al cartone</h2><p>Utilizziamo imballaggi a base di cartone adatti ai flussi di riciclo esistenti. La selezione viene valutata tramite schede tecniche, dichiarazioni e, quando necessario, rapporti di prova. La riciclabilità dipende anche dalle infrastrutture locali e dalle condizioni effettive d’uso.</p><h2>Metalli pesanti e articolo 5</h2><p>L’articolo 5 limita a 100 mg/kg per componente d’imballaggio la somma di piombo, cadmio, mercurio e cromo esavalente. Rotabil controlla questo requisito attraverso le evidenze aggiornate dei fornitori e la tracciabilità dei materiali.</p><h2>PFAS e contatto alimentare</h2><p>I limiti PFAS del PPWR riguardano gli imballaggi a contatto con alimenti. Dal 12 agosto 2026 le soglie sono 25 ppb per ogni PFAS, 250 ppb per la somma dei PFAS mirati quando applicabile e 50 ppm per i PFAS totali, inclusi quelli polimerici. Questa pagina non è un certificato di idoneità al contatto alimentare.</p><h2>Validità e tracciabilità</h2><ul><li>Dichiarazioni e rapporti di prova dei fornitori vengono riesaminati e rinnovati ogni anno.</li><li>I registri interni collegano le informazioni tecniche a fornitore, codice prodotto e lotto.</li><li>Ogni modifica a materiale o fornitore attiva una nuova revisione documentale.</li></ul><h2>EPR e peso degli imballaggi</h2><p>Gli obblighi di responsabilità estesa del produttore dipendono dal mercato, dal ruolo delle parti e dalle regole locali. Su richiesta possiamo condividere i dati disponibili su tipo e peso dell’imballaggio. Gli obblighi di dichiarazione vanno verificati per ciascun Paese.</p><h2>Domande e documenti</h2><p>Per domande sul nostro approccio PPWR o sui documenti dei fornitori, scrivere a <a href="mailto:info@rotabiletiket.com">info@rotabiletiket.com</a>.</p><p><a href="/docs/ppwr-karton-ambalaj-uygunluk-beyani.pdf" download>Scarica la dichiarazione PPWR per imballaggi in cartone (PDF)</a></p><p><small><strong>Ultimo aggiornamento:</strong> 16 luglio 2026. Informazioni generali, non consulenza legale.</small></p><p><small>Fonti: <a href="https://eur-lex.europa.eu/eli/reg/2025/40/ojS" rel="nofollow">PPWR UE 2025/40</a> e la <a href="https://environment.ec.europa.eu/topics/waste-and-recycling/packaging-waste_en" rel="nofollow">pagina della Commissione europea</a>.</small></p>', 'PPWR (UE) 2025/40: approccio di Rotabil agli imballaggi in cartone riciclabili, tracciabilità ed EPR.', 'PPWR, UE 2025/40, imballaggi in cartone, riciclabilità, PFAS, metalli pesanti, EPR'),
  (article_id, 'ar', 'اللائحة PPWR (الاتحاد الأوروبي) 2025/40: نهج روتابيل في عبوات الكرتون', 'ppwr-eu-2025-40-rotabil-carton-packaging-compliance-ar', 'نهج روتابيل الموثق تجاه عبوات الكرتون القابلة لإعادة التدوير وأدلة الموردين والتتبع ومعلومات مسؤولية المنتج الممتدة.', '<p>تضع اللائحة الأوروبية 2025/40 الخاصة بالعبوات ونفايات العبوات إطاراً موحداً لتصميم العبوات وتركيبها وقابليتها لإعادة التدوير وإدارة النفايات. دخلت اللائحة حيز التنفيذ في 11 فبراير 2025، ويبدأ تطبيقها العام في 12 أغسطس 2026.</p><div style="background:#fff7ed;border-right:4px solid #f97316;padding:1rem 1.25rem;margin:1.5rem 0"><strong>نطاق روتابيل:</strong> يغطي هذا البيان عبوات الكرتون القابلة لإعادة التدوير المستخدمة لشحن منتجاتنا وتعبئتها، والمدعومة بإقرارات الموردين والوثائق الفنية الحالية. ولا يمثل إقراراً شاملاً لكل منتج أو استخدام.</div><h2>نهجنا تجاه عبوات الكرتون</h2><p>نستخدم عبوات قائمة على الكرتون ومناسبة لمسارات إعادة التدوير المعتمدة. نقيم اختيار المواد من خلال أوراق البيانات الفنية وإقرارات الموردين وتقارير الاختبار عند الحاجة.</p><h2>المعادن الثقيلة بموجب المادة 5</h2><p>تحدد المادة 5 مجموع الرصاص والكادميوم والزئبق والكروم سداسي التكافؤ بحد أقصى 100 ملغم/كغم لكل مكوّن من مكونات العبوة. نتابع هذا المتطلب من خلال أدلة الموردين الحالية وإمكانية تتبع المواد.</p><h2>PFAS وملامسة الغذاء</h2><p>تتعلق حدود PFAS في اللائحة بالعبوات الملامسة للغذاء. اعتباراً من 12 أغسطس 2026، تبلغ الحدود 25 جزءاً في البليون لأي PFAS و250 جزءاً في البليون لمجموع PFAS المحددة عند انطباق ذلك و50 جزءاً في المليون لمجموع PFAS بما فيها البوليمرية. هذه الصفحة ليست شهادة صلاحية لملامسة الغذاء.</p><h2>الصلاحية والتتبع</h2><ul><li>تتم مراجعة إقرارات الموردين وتقارير الاختبار وتجديدها سنوياً.</li><li>تربط سجلاتنا الداخلية المعلومات الفنية بالمورد ورمز المنتج ورقم الدفعة.</li><li>يؤدي أي تغيير في المادة أو المورد إلى مراجعة جديدة للوثائق.</li></ul><h2>مسؤولية المنتج الممتدة وبيانات الوزن</h2><p>تختلف الالتزامات حسب السوق ودور الأطراف والقواعد المحلية. وبناءً على الطلب، يمكننا مشاركة بيانات نوع العبوة ووزنها المتاحة لدعم إجراءات الامتثال لدى العملاء. يجب التحقق من مسؤوليات الإبلاغ والتمويل في كل دولة.</p><h2>الأسئلة والوثائق</h2><p>للاستفسار تواصلوا معنا عبر <a href="mailto:info@rotabiletiket.com">info@rotabiletiket.com</a>.</p><p><a href="/docs/ppwr-karton-ambalaj-uygunluk-beyani.pdf" download>تحميل بيان عبوات الكرتون وفق PPWR بصيغة PDF</a></p><p><small><strong>آخر تحديث:</strong> 16 يوليو 2026. معلومات عامة وليست استشارة قانونية.</small></p><p><small>المصادر: <a href="https://eur-lex.europa.eu/eli/reg/2025/40/ojS" rel="nofollow">اللائحة الأوروبية 2025/40</a> و<a href="https://environment.ec.europa.eu/topics/waste-and-recycling/packaging-waste_en" rel="nofollow">صفحة المفوضية الأوروبية</a>.</small></p>', 'اللائحة PPWR (الاتحاد الأوروبي) 2025/40: نهج روتابيل تجاه عبوات الكرتون القابلة لإعادة التدوير والتتبع.', 'PPWR, EU 2025/40, carton packaging, recyclability, PFAS, EPR')
